import "server-only";
import fs from "node:fs/promises";
import path from "node:path";
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { env } from "@/server/config/env";

/**
 * Private document storage abstraction. Keys are opaque and generated by the server
 * (`applications/<applicationId>/<uuid>`); user input never becomes part of a path.
 */
export interface StorageDriver {
  readonly name: "local" | "s3";
  put(key: string, bytes: Buffer, contentType: string): Promise<void>;
  /** Short-lived signed URL (S3) or null when the app must stream the bytes itself (local). */
  signedDownloadUrl(key: string, opts: { filename: string; contentType: string; inline: boolean }): Promise<string | null>;
  read(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^applications\/[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

export function assertValidKey(key: string) {
  if (!KEY_PATTERN.test(key)) throw new Error("Invalid storage key");
}

function contentDisposition(filename: string, inline: boolean) {
  const safe = filename.replace(/[^\w.\- ]+/g, "_").slice(0, 120) || "document";
  return `${inline ? "inline" : "attachment"}; filename="${safe}"; filename*=UTF-8''${encodeURIComponent(safe)}`;
}

/** Development driver: files under a private directory outside /public, never web-served directly. */
class LocalStorageDriver implements StorageDriver {
  readonly name = "local" as const;
  private root = path.resolve(env().LOCAL_STORAGE_DIR);
  private resolve(key: string) {
    assertValidKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(this.root + path.sep)) throw new Error("Invalid storage key");
    return full;
  }
  async put(key: string, bytes: Buffer) {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, bytes, { mode: 0o600 });
  }
  async signedDownloadUrl() {
    return null;
  }
  async read(key: string) {
    return fs.readFile(this.resolve(key));
  }
  async delete(key: string) {
    await fs.rm(this.resolve(key), { force: true });
  }
}

class S3StorageDriver implements StorageDriver {
  readonly name = "s3" as const;
  private client: S3Client;
  private bucket: string;
  constructor() {
    const e = env();
    if (!e.S3_BUCKET || !e.S3_REGION) throw new Error("S3_BUCKET and S3_REGION are required for STORAGE_DRIVER=s3");
    this.bucket = e.S3_BUCKET;
    this.client = new S3Client({
      region: e.S3_REGION,
      endpoint: e.S3_ENDPOINT || undefined,
      forcePathStyle: e.S3_FORCE_PATH_STYLE,
      credentials:
        e.S3_ACCESS_KEY_ID && e.S3_SECRET_ACCESS_KEY ? { accessKeyId: e.S3_ACCESS_KEY_ID, secretAccessKey: e.S3_SECRET_ACCESS_KEY } : undefined,
    });
  }
  async put(key: string, bytes: Buffer, contentType: string) {
    assertValidKey(key);
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: bytes,
        ContentType: contentType,
        ServerSideEncryption: env().S3_ENDPOINT ? undefined : "AES256",
      }),
    );
  }
  async signedDownloadUrl(key: string, opts: { filename: string; contentType: string; inline: boolean }) {
    assertValidKey(key);
    return getSignedUrl(
      this.client,
      new GetObjectCommand({
        Bucket: this.bucket,
        Key: key,
        ResponseContentDisposition: contentDisposition(opts.filename, opts.inline),
        ResponseContentType: opts.contentType,
        ResponseCacheControl: "no-store",
      }),
      { expiresIn: env().SIGNED_URL_TTL_SECONDS },
    );
  }
  async read(key: string) {
    assertValidKey(key);
    const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    const bytes = await res.Body?.transformToByteArray();
    if (!bytes) throw new Error("Empty object");
    return Buffer.from(bytes);
  }
  async delete(key: string) {
    assertValidKey(key);
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }
}

let driver: StorageDriver | null = null;
export function getStorage(): StorageDriver {
  if (!driver) driver = env().STORAGE_DRIVER === "s3" ? new S3StorageDriver() : new LocalStorageDriver();
  return driver;
}

export { contentDisposition };
